import json,re
from pathlib import Path
root=Path(__file__).resolve().parents[1]
common={
'OfficialName':'FullName','RankRate':'Rate','Designator':'Desig','MemberSSN':'SSN','MemberDoDID':'DoDID',
'UnitUIC':'UIC','ShipStation':'ShipStation','PromotionStatus':'PromotionStatus',
'PeriodStart':'FromDate','PeriodEnd':'ToDate','DateReported':'DateReported',
'OccasionPeriodic':'Periodic','OccasionDetachment':'DetInd','OccasionFrocking':'Frocking','OccasionSpecial':'Special',
'ReportRegular':'Regular','ReportConcurrent':'Concurrent','ReportOperationalCommander':'OpsCdr',
'ComponentActive':'Active','ComponentTAR':'TAR','ComponentInactive':'Inactive','ComponentATADSW':'ATADSW',
'ObservationStatus':'NOB','PromotionRecommendation':'PromotionRecom',
'ReportingSeniorName':'ReportingSenior','ReportingSeniorGrade':'RSGrade','ReportingSeniorDesignator':'RSDesig','ReportingSeniorTitle':'RSTitle','ReportingSeniorUIC':'RSUIC',
'ReportingSeniorSSN':'RSSSN','ReportingSeniorDoDID':'RSDoDID',
'PrimaryDuty':'PrimaryDuty','DutyDescription':'Duties','CounselingDate':'DateCounseled','CounselorName':'Counseler',
'ReadinessSummary':'PhysicalReadiness','ReadinessDetail':'PhysicalReadiness2','ReadinessDate':'PhysicalReadinessDt','BilletSubcategory':'BilletSubcat',
'AssignmentRecommendationA':'RecommendA','AssignmentRecommendationB':'RecommendB','OfficialComments':'Comments',
'RetentionYes':'RetentionYes','RetentionNo':'RetentionNo','StatementYes':'StatementYes','StatementNo':'StatementNo',
'ReportingSeniorAddress1':'RSAddress1','ReportingSeniorAddress2':'RSAddress2','ReportingSeniorCity':'RSCity','ReportingSeniorState':'RSState','ReportingSeniorZip':'RSZipCd','ReportingSeniorPhone':'RSPhone','ReportingSeniorDSN':'RSDSN',
'RaterName':'Rater','RaterDate':'RaterDate','SeniorRaterName':'SeniorRater','SeniorRaterDate':'SeniorRaterDate',
'MemberFirstName':'FirstName','MemberMiddleInitial':'MI','MemberLastName':'LastName','MemberSuffix':'Suffix',
'ReportingSeniorLastName':'RSLastName','ReportingSeniorFirstInitial':'RSFI','ReportingSeniorMiddleInitial':'RSMI',
'CounselorLastName':'CounselerLN','CounselorFirstInitial':'CounselerFI','CounselorMiddleInitial':'CounselerMI'}
flags=set('OccasionPeriodic OccasionDetachment OccasionFrocking OccasionSpecial ReportRegular ReportConcurrent ReportOperationalCommander ComponentActive ComponentTAR ComponentInactive ComponentATADSW RetentionYes RetentionNo StatementYes StatementNo'.split())
dates=set('PeriodStart PeriodEnd DateReported ReadinessDate RaterDate SeniorRaterDate'.split())
traits={'EVAL':'PROF QUAL EO MIL PA TEAM LEAD','CHIEFEVAL':'LEAD TAC PROF MIS EO TEAM MIL','FITREP':'PROF EO MIL TEAM MIS LEAD TAC'}
catalogue={}; lines=['Attribute VB_Name = "modNAVFITMapping"','Option Compare Binary','Option Explicit',"' Generated by scripts/generate-navfit-map.py; native reference database determines trait order.",'Public Function NAVFITMapRows(ByVal kind As String) As Collection','    Dim result As New Collection','    Select Case kind']
for kind,names in traits.items():
    rows=[]
    for target,source in common.items():
        conversion='flag' if target in flags else 'date' if target in dates else 'observation' if target=='ObservationStatus' else 'promotion' if target=='PromotionRecommendation' else 'counseling' if target=='CounselingDate' else 'text'
        rows.append(dict(target=target,source=source,conversion=conversion))
    rows += [dict(target=f'Trait{i}',source=name,conversion='trait') for i,name in enumerate(names.split(),33)]
    catalogue[kind]=rows
    lines.append(f'        Case "{kind}"')
    lines += [f'            result.Add "{r["target"]}|{r["source"]}|{r["conversion"]}"' for r in rows]
lines += ['        Case Else: Err.Raise vbObjectError + 5100, , "Unsupported NAVFIT report type."','    End Select','    Set NAVFITMapRows = result','End Function']
(root/'src/navfit-field-map.json').write_text(json.dumps(catalogue,indent=2)+'\n')
(root/'src/modNAVFITMapping.bas').write_bytes(('\r\n'.join(lines)+'\r\n').encode('ascii'))
assert all(len(rows)==74 for rows in catalogue.values()), [len(x) for x in catalogue.values()]
